def typed(raw):
 need(type(raw)is bytes and len(raw)==44,'exact five-entry default ACL encoding')
 need(struct.unpack_from('<I',raw)[0]==2,'canonical Linux ACL version2')
 entries=[struct.unpack_from('<HHI',raw,4+8*i)for i in range(5)]
 need(tuple(r[0]for r in entries)==(1,4,8,16,32),'canonical default ACL tag/order/cardinality')
