 adapted_node=next(n for n in ast.parse(adapted).body if isinstance(n,ast.FunctionDef)and n.name=='_attrs');exec(compile(ast.Module(body=[adapted_node],type_ignores=[]),'file_capabilities-scoped.py','exec'),vars(observer));X.install(observer,adapted.encode())
